import { ARBITRUM, ARBITRUM_SEPOLIA, AVALANCHE, AVALANCHE_FUJI, MEGAETH } from "./chains";
const API_URLS = {
    production: {
        [ARBITRUM]: "https://arbitrum.gmxapi.io",
        [AVALANCHE]: "https://avalanche.gmxapi.io",
        [AVALANCHE_FUJI]: undefined,
        [ARBITRUM_SEPOLIA]: "https://arbitrum-sepolia-test.gmxapi.ai",
        [MEGAETH]: "https://megaeth.gmxapi.io",
    },
    test: {
        [ARBITRUM]: "https://arbitrum-test.gmxapi.ai",
        [AVALANCHE]: undefined,
        [AVALANCHE_FUJI]: undefined,
        [ARBITRUM_SEPOLIA]: "https://arbitrum-sepolia-test.gmxapi.ai",
        [MEGAETH]: undefined,
    },
};
const API_FALLBACK_URLS = {
    production: {
        [ARBITRUM]: [],
        [AVALANCHE]: [],
        [AVALANCHE_FUJI]: [],
        [ARBITRUM_SEPOLIA]: [],
        [MEGAETH]: [],
    },
    test: {
        [ARBITRUM]: [],
        [AVALANCHE]: [],
        [AVALANCHE_FUJI]: [],
        [ARBITRUM_SEPOLIA]: [],
        [MEGAETH]: [],
    },
};
export function getApiUrl(chainId, environment = "production") {
    return API_URLS[environment][chainId];
}
export function getApiFallbackUrls(chainId, environment = "production") {
    return API_FALLBACK_URLS[environment][chainId] ?? [];
}
export function isApiSupported(chainId, environment = "production") {
    return getApiUrl(chainId, environment) !== undefined;
}
// Stats are chain-agnostic, so one deployment per environment serves them for every network
const STATS_API_URLS = {
    production: API_URLS.production[ARBITRUM],
    test: API_URLS.test[ARBITRUM],
};
export function getStatsApiUrl(environment = "production") {
    return STATS_API_URLS[environment];
}
